<template>
  <div><el-button link type="primary" @click="router.back()">← 返回琴房列表</el-button><el-card v-if="room" class="soft-card detail-card" shadow="never"><div class="detail-head"><div><div><el-tag :type="room.roomType === 'inner' ? 'warning' : 'success'">{{ room.roomType === 'inner' ? '对内琴房' : '对外琴房' }}</el-tag></div><h1 class="page-title">{{ room.name }}</h1><p class="page-subtitle">开放时间：{{ minuteToTime(room.openStart) }} - {{ minuteToTime(room.openEnd) }}</p></div><el-button plain @click="loadFree">刷新空闲</el-button></div><el-divider /><el-row :gutter="28"><el-col :xs="24" :md="14"><h3>琴房说明</h3><p class="description">{{ room.description || '暂无说明' }}</p><h3>乐器明细</h3><el-table v-if="instruments.length" :data="instruments" size="small"><el-table-column prop="name" label="乐器" /><el-table-column prop="count" label="数量" width="80" /><el-table-column prop="note" label="备注" /></el-table><el-empty v-else description="暂无乐器信息" /></el-col><el-col :xs="24" :md="10"><el-card class="booking-panel" shadow="never"><h3>选择预约时段</h3><el-alert v-if="risk.active" class="risk-alert" :title="risk.reason || '预约服务暂时受限'" type="warning" :closable="false" show-icon><template #default>临近取消次数：{{ risk.nearCancelCount }}。预约服务将于 {{ risk.until }} 恢复。</template></el-alert><el-date-picker v-model="date" type="date" value-format="YYYY-MM-DD" :disabled-date="disableDate" :clearable="false" @change="loadFree" /><div class="slot-title">可用区间</div><div v-if="freeSlots.length" class="slots"><el-tag v-for="slot in freeSlots" :key="`${slot.startMin}-${slot.endMin}`" class="slot" effect="plain" @click="chooseSlot(slot)">{{ timeRange(slot) }}</el-tag></div><el-empty v-else description="当天暂无空闲时段" :image-size="70" /><el-form label-position="top" class="booking-form"><el-form-item label="开始时间"><el-select v-model="form.startMin" placeholder="选择开始时间"><el-option v-for="value in starts" :key="value" :label="minuteToTime(value)" :value="value" /></el-select></el-form-item><el-form-item label="结束时间"><el-select v-model="form.endMin" placeholder="选择结束时间"><el-option v-for="value in ends" :key="value" :label="minuteToTime(value)" :value="value" /></el-select></el-form-item><el-button type="primary" :loading="submitting" :disabled="risk.active" class="full-btn" @click="submitBooking">确认预约</el-button></el-form><el-divider /><div class="watch-title">没有空闲？关注想要的时段</div><el-form label-position="top" class="booking-form"><el-form-item label="关注开始"><el-select v-model="watchForm.startMin" placeholder="选择开始时间"><el-option v-for="value in watchStarts" :key="value" :label="minuteToTime(value)" :value="value" /></el-select></el-form-item><el-form-item label="关注结束"><el-select v-model="watchForm.endMin" placeholder="选择结束时间"><el-option v-for="value in watchEnds" :key="value" :label="minuteToTime(value)" :value="value" /></el-select></el-form-item><el-button plain :loading="watching" class="full-btn" @click="submitWatch">关注该时段</el-button></el-form></el-card></el-col></el-row></el-card><el-skeleton v-else-if="loading" :rows="8" animated /><el-empty v-else description="琴房不存在或加载失败" /></div>
</template>
<script setup>
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue'; import { ElMessage } from 'element-plus'; import { useRoute, useRouter } from 'vue-router'; import { createBooking } from '../api/bookings'; import { getNearCancelRisk } from '../api/risk'; import { addWatch } from '../api/watches'; import { getFreeSlots, getRoom } from '../api/rooms'; import { getRules } from '../api/content'; import { minuteToTime, timeRange, todayString } from '../utils/time'; import { throttle } from '../utils/rate'
const route=useRoute(); const router=useRouter(); const room=ref(null); const instruments=ref([]); const freeSlots=ref([]); const loading=ref(true); const submitting=ref(false); const watching=ref(false); const date=ref(todayString()); const form=reactive({startMin:null,endMin:null}); const watchForm=reactive({startMin:null,endMin:null}); const minUnit=ref(30); const advanceDays=ref(7); const riskEnabled=import.meta.env.VITE_NEAR_CANCEL_RISK_ENABLED==='true'; const risk=ref({active:false,until:'',reason:'',nearCancelCount:0})
const starts=computed(()=>freeSlots.value.flatMap(slot=>{const values=[];for(let n=slot.startMin;n<slot.endMin;n+=minUnit.value) values.push(n);return values})); const ends=computed(()=>freeSlots.value.flatMap(slot=>{const values=[];for(let n=slot.startMin+minUnit.value;n<=slot.endMin;n+=minUnit.value) values.push(n);return values}));
const watchStarts=computed(()=>{const values=[];for(let n=room.value?.openStart||0;n<(room.value?.openEnd||0)-minUnit.value;n+=minUnit.value) values.push(n);return values}); const watchEnds=computed(()=>{const values=[];for(let n=(room.value?.openStart||0)+minUnit.value;n<= (room.value?.openEnd||0);n+=minUnit.value) values.push(n);return values})
function disableDate(d){ const now=new Date(); now.setHours(0,0,0,0); const max=new Date(now); max.setDate(max.getDate()+advanceDays.value); return d<now||d>max }
function applyRiskStatus(status){if(!status?.active&&!status?.until)return false;risk.value={active:true,until:status.until||'稍后',reason:status.reason||'临近预约开始时段的退约次数达到上限',nearCancelCount:Number(status.nearCancelCount)||0};return true}
async function loadRisk(){if(!riskEnabled)return;try{const status=await getNearCancelRisk();if(!applyRiskStatus(status))risk.value={active:false,until:'',reason:'',nearCancelCount:0}}catch{}}
async function load(){ loading.value=true; try { const data=await getRoom(route.params.id); room.value=data.room; instruments.value=data.instruments||[]; try { const rules=await getRules(); minUnit.value=Number(rules?.['booking.minUnit'])||30; advanceDays.value=Number(rules?.['booking.advanceDays'])||7 } catch {} await loadFree(); void loadRisk() } catch(e){ ElMessage.error(e.message) } finally{ loading.value=false } }
async function fetchFreeSlots(){ if(!room.value && !route.params.id)return; try{ freeSlots.value=await getFreeSlots(route.params.id,date.value)||[]; form.startMin=null; form.endMin=null }catch(e){ freeSlots.value=[]; ElMessage.warning(e.message) } }
const loadFree = throttle(fetchFreeSlots, 250)
function chooseSlot(slot){form.startMin=slot.startMin;form.endMin=slot.endMin}
function valid(){ if(form.startMin==null||form.endMin==null||form.startMin>=form.endMin){ElMessage.warning('请选择有效的预约区间');return false} return freeSlots.value.some(s=>form.startMin>=s.startMin&&form.endMin<=s.endMin) }
function operationError(e, fallback){return String(e.code)==='429'?'操作过于频繁，请稍后再试':e.message||fallback}
async function submitBooking(){if(!valid()||submitting.value||risk.value.active)return;submitting.value=true;try{await createBooking({roomId:Number(route.params.id),bookDate:date.value,startMin:form.startMin,endMin:form.endMin});ElMessage.success('预约成功');router.push('/bookings')}catch(e){if(String(e.code)==='409'&&applyRiskStatus(e.data))ElMessage.warning(operationError(e,'预约服务暂时受限'));else if(String(e.code)==='409'||String(e.code)==='429')ElMessage.warning(operationError(e,'该时段不可预约'));else ElMessage.error(operationError(e,'预约失败，请稍后重试'))}finally{submitting.value=false}}
async function submitWatch(){if(watchForm.startMin==null||watchForm.endMin==null||watchForm.startMin>=watchForm.endMin){ElMessage.warning('请选择有效的关注区间');return}if(watching.value)return;watching.value=true;try{await addWatch({roomId:Number(route.params.id),bookDate:date.value,startMin:watchForm.startMin,endMin:watchForm.endMin});ElMessage.success('已关注该时段')}catch(e){ElMessage.warning(operationError(e,'关注失败，请稍后重试'))}finally{watching.value=false}}
onMounted(load); onUnmounted(loadFree.cancel)
</script>
<style scoped>.detail-card{margin-top:14px}.detail-head{display:flex;justify-content:space-between;align-items:flex-start}.detail-head h1{margin-top:16px}.description{color:#5f7279;line-height:1.9;min-height:52px}.booking-panel{background:#f8fbfb;border:1px solid #e5f0ef}.booking-panel h3{margin-top:0}.risk-alert{margin:0 0 18px}.slot-title,.watch-title{margin:24px 0 10px;color:#60747a;font-size:13px}.watch-title{font-weight:700;color:#168f83}.slots{display:flex;flex-wrap:wrap;gap:8px}.slot{cursor:pointer}.booking-form{margin-top:20px}.booking-form .el-select,.booking-form .el-date-editor{width:100%}.full-btn{width:100%;margin:0 0 10px}.full-btn+.full-btn{margin-left:0}
</style>
